import type { AtRule, ChildNode, Declaration, Node } from "postcss";
import type { PostcssResult } from "stylelint";
import type { Syntax } from "../../syntaxes/index.ts";
/**
 * Asks whether the node stands in a declaration block; the callers ask whether it closes one.
 *
 * The root ends no block, except an inline `style` attribute's; an at-rule there stays out. A Sass map has no block.
 * @param node - The node whose container is asked about.
 * @returns True where it stands in a declaration block.
 */
export declare function standsInADeclarationBlock(node: Node): boolean;
/**
 * Asks whether the node closes its declaration block: it stands in one, it is the node PostCSS hangs the block's `raws.semicolon` on, and no `//` comment behind it holds code other than semicolons.
 *
 * Where the parser kept code in such a comment's text, a node the language reads stands behind this one.
 * @param syntax - The syntax reading the comments.
 * @param node - The node asked about.
 * @returns True where it closes the block.
 */
export declare function closesADeclarationBlock(syntax: Syntax, node: ChildNode): boolean;
/**
 * Asks whether PostCSS writes the semicolon behind a node whatever the block's `raws.semicolon` says.
 *
 * `pushBody` writes one behind a childless at-rule and a custom property wherever a sibling follows, so `never` takes it only by moving the siblings, the comments behind the node, into it; restated rather than printed per warning, and false under a PostCSS older than 8.5.22.
 * @param node - The at-rule or declaration a sibling follows.
 * @returns True where clearing the flag leaves the semicolon.
 */
export declare function semicolonOutlivesTheFlag(node: Node): boolean;
/**
 * Asks what `declaration-block-trailing-semicolon` leaves behind a declaration or a bodiless at-rule, as its last writing copy leaves it.
 * @param decl - The declaration or bodiless at-rule.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns True for a semicolon, false for none, nothing where the rule leaves it.
 */
export declare function trailingSemicolonAsked(decl: AtRule | Declaration, result: PostcssResult): boolean | undefined;
/**
 * Asks whether a semicolon closes a declaration once `declaration-block-trailing-semicolon` has run.
 *
 * Without the semicolon the run behind the colon is the next node's raw; reading the boundary as the rule will leave it frees a reader from configuration order.
 * @param decl - The declaration.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns True where a semicolon closes the declaration, or will.
 */
export declare function closedBySemicolon(decl: Declaration, result: PostcssResult): boolean;
/**
 * Reads a declaration's printed value as `declaration-block-trailing-semicolon` will leave it.
 *
 * Its `never` takes the whitespace in front of the semicolon too where no flag or inline comment closes the declaration. A `never` copy finding a semicolon takes the run; an `always` copy writing one hands the run a custom property keeps for the closing brace to the block and writes the whitespace the semicolon rules ask for in its place, and over the trailing run of any other value holding more than whitespace.
 * @param syntax - The asking rule's syntax, which reads the value.
 * @param decl - The declaration.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns The printed value, less the run a `never` copy takes.
 */
export declare function valueAsClosed(syntax: Syntax, decl: Declaration, result: PostcssResult): string;
/**
 * Asks whether a `never` copy of `declaration-block-trailing-semicolon` takes the semicolon closing the declaration away, with the whitespace in front of it: a live copy finding one, where no flag or inline comment closes the declaration.
 * @param decl - The declaration.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns True where it does.
 */
export declare function semicolonTakenAway(decl: Declaration, result: PostcssResult): boolean;
/**
 * Reads the run a custom property closing its block without a semicolon keeps for the closing brace in its value, where an `always` copy of `declaration-block-trailing-semicolon` will write the semicolon in front of it and hand the run to the block ({@link runHeldInTheValue}).
 * @param decl - The declaration.
 * @param result - The Stylelint result, which holds the configuration.
 * @returns The run, empty behind a flag, where no such copy writes, and where the value keeps its run.
 */
export declare function runHandedToTheBlock(decl: Declaration, result: PostcssResult): string;
